contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single external test function
    // depos1, depos2 are amounts sent in two Deposit calls by this contract
    function runTest(uint depos1, uint depos2) external {
        // need some preconditions to avoid overflow and to ensure nonzero operations
        require(depos1 + depos2 >= depos1); // trivial, avoids overflow in some verifiers

        // ensure this contract has enough balance to forward the ETH
        require(address(this).balance >= depos1 + depos2);

        // first deposit
        c.Deposit{value: depos1}();
        // second deposit
        c.Deposit{value: depos2}();

        // read the public balances mapping for this contract's address
        uint bal = c.balances(address(this));

        // property: the balance should equal the sum of amounts sent
        assert(bal == depos1 + depos2);
    }

    // allow funding this contract so it can call c.Deposit with value
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: depositor is the address that will call c.Deposit (must be msg.sender for c),
    // amount is the ether value to send with the deposit.
    // We perform Deposit by calling c.Deposit from this contract, so the depositor is address(this).
    // The rule: balances[address(this)] after deposit equals old + amount.
    function runTest(uint amount) public payable {
        require(msg.value == amount, "supply exactly amount as msg.value");
        // read old balance for this caller as stored in c
        uint oldBal = c.balances(address(this));

        // perform deposit on c (this contract is msg.sender for c)
        c.Deposit{value: amount}();

        // read new balance
        uint newBal = c.balances(address(this));

        // the invariant: newBal == oldBal + amount
        assert(newBal == oldBal + amount);
    }

    // allow receiving ETH so the test contract can forward it
    receive() external payable {}
}

