contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test driving contract c: one depositor sends value 'amt'.
    // Asserts that balances(depositor) equals prior balance + amt.
    function check_deposit(address payable depositor, uint256 amt) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amt, "insufficient balance to forward");

        // read prior balance
        uint256 before = c.balances(depositor);

        // perform deposit from this contract on behalf of depositor by calling c with .call as msg.sender must be depositor
        // We cannot make c see msg.sender as 'depositor' unless depositor is this contract.
        // So require depositor == address(this) to make the test valid: the caller of c.Deposit must be this contract.
        require(depositor == address(this), "depositor must be this contract for call to originate from here");

        // perform the deposit: this contract calls c.Deposit sending amt
        c.Deposit{value: amt}();

        // read after balance
        uint256 after = c.balances(depositor);

        // invariant: balance increased by exactly amt
        assert(after == before + amt);
    }

    // allow this contract to receive ETH to fund deposits
    receive() external payable {}
}

