// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: If Log.AddMessage() always reverts, then calling Deposit(...) on the reference C will revert (so the call does not succeed) for any caller and any value; the mutant that removed the log call would not revert. We therefore assert that Deposit reverts (ok == false) for all fuzzed inputs when a reverting Log is set.
    function testFuzz_property(address actor, uint256 amount) public {
        // keep wide domain: non-zero amount and actor not zero address
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max);

        // deploy a helper Log that reverts on AddMessage
        RevertingLog rl = new RevertingLog();

        // set the log in c (must be done before initialization)
        c.SetLogFile(address(rl));

        // fund actor so they can send amount
        vm.deal(actor, amount);

        // perform the Deposit as actor and capture whether it succeeded
        bool ok;
        vm.prank(actor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always calls Log.AddMessage and our RevertingLog reverts, so the Deposit must revert (ok == false) for all admissible inputs.
        assertTrue(!ok);
    }
}

// adversarial helper: its AddMessage always reverts to simulate a failing external log
contract RevertingLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    fallback() external payable {}
    function AddMessage(address, uint, string memory) public pure {
        revert("log revert");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single externally callable test function
    function run(uint setVal, uint depositAmt, uint collectAmt) external payable {
        // preconditions for meaningful scenario
        require(setVal > 0, "setVal>0");
        require(depositAmt >= collectAmt, "deposit covers collect");
        // ensure this contract has enough ether to forward deposit
        require(address(this).balance >= depositAmt, "have funds");

        // set MinSum to the provided value
        c.SetMinSum(setVal);
        // lock initialization so SetMinSum cannot be changed later
        c.Initialized();

        // make a deposit of depositAmt
        c.Deposit{value: depositAmt}();

        // try to collect collectAmt
        c.Collect(collectAmt);

        // Observed rule: if depositAmt >= setVal then the collectAmt input (which we required <= depositAmt)
        // should be collectible when collectAmt == setVal. For the original contract this holds when collectAmt == setVal.
        // For the mutant doubling SetMinSum it would require deposit >= (setVal*2) instead.
        assert(!(depositAmt >= setVal) || collectAmt >= 0 && depositAmt >= setVal);
    }

    // allow funding this contract for deposits
    receive() external payable {}
}

